import os;os.environ['OPENBLAS_NUM_THREADS']='1'
import sys;sys.path.insert(0,'/app/output')
import numpy as np,multiprocessing as mp
from rcb_hb import Session
from control import Controller
PREFIX=np.load('/app/hook2.npz')['actions'][:560]
BP=np.load('/app/best_params.npz')['params']
def init():
 global s,c0
 s=Session(instance='/app/instance.npz');c0=Controller(s)
def run(p,save=False):
 s.replay(PREFIX);c=Controller(s);c.feet=c0.feet.copy();c.feet[0,0]+=.18*59/60;c.feet[1,0]+=.27*59/60;c.qref=c0.qref.copy();c.qref[11:15]=[-1.4,.9,3.6,0];c.com=np.array([.28,0,1.0]);c.handrot[7]=BP[8:11]/np.linalg.norm(BP[8:11]);c.pelvis[2]=.98
 start=np.array([.68,.30,1.28]);press=BP[:3];pull=BP[3:6];dur=int(BP[6]);hold=int(BP[7]);acts=[];states=[];score=0;maxdoor=0
 for t in range(440):
  if t<dur:u=(t+1)/dur;target=start*(1-u)+press*u
  elif t<dur+hold:target=press
  else:u=np.clip((t-dur-hold)/100,0,1);target=press*(1-u)+pull*u
  c.hands[7]=target
  if t>=p[0]:
   a=s.data.qpos[26];h=s.data.qpos[27];R=np.array([[np.cos(a),-np.sin(a),0],[np.sin(a),np.cos(a),0],[0,0,1]])
   handle=np.array([-.09,.9-.1*np.cos(h),1.2-.1*np.sin(h)])
   goal=np.array([.75,-.5,0])+R@(handle+p[1:4]);u=np.clip((t-p[0])/p[4],0,1);c.hands[7]=(1-u)*target+u*goal
   c.com[:2]=p[5:7]
   if p[7]>0:vec=R@np.array([p[8],p[9],-1]);c.handrot[7]=vec/np.linalg.norm(vec)
   else:c.handrot.pop(7,None)
  a=c.action();_,_,done=s.step(a);acts.append(a);states.append(s.data.qpos.copy());door=s.data.qpos[26];maxdoor=max(maxdoor,door);score+=max(door,0)*3+.02*(s.data.qpos[2]>.8)
  if done:break
 score+=maxdoor*30
 if save:np.savez('/app/search_fast_best.npz',actions=np.r_[PREFIX,np.array(acts)],states=states,params=p)
 return score,maxdoor,len(acts),p
