 rng=np.random.default_rng(31);ps=[]
 for i in range(256):ps.append(np.r_[rng.uniform(85,145),rng.uniform(-.45,-.1),rng.uniform(-.1,.4),rng.uniform(-.16,.12),rng.uniform(10,70),rng.uniform(.15,.4),rng.uniform(-.25,.1),rng.uniform(-1,1),rng.uniform(-.5,.5),rng.uniform(-.5,.5)])
 with mp.Pool(16,initializer=init) as pool:
  best=(-1,)
  for i,r in enumerate(pool.imap_unordered(run,ps)):
   if r[0]>best[0]:best=r;print(i,'BEST',r,flush=True);np.savez('/app/fast_params.npz',params=r[3])
 init();print('final',run(best[3],True),flush=True)
